// audit/parse.mjs — turn one fetched document into a Page object.
//
// The rules never read HTML. They read this object, which means a rule cannot
// quietly depend on a regex that only works on one template, and the parser can
// be tested once instead of in every rule.
//
// The HTML here is generated by our own build.mjs, so the shape is predictable.
// That is why plain regex is defensible: there are no hand-authored pages, no
// CMS, no tag soup. The one risk — a `</script>` inside JSON-LD — is impossible
// by construction, because build.mjs escapes `<` inside every ld+json block.

const ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', hellip: '…',
  mdash: '—', ndash: '–', rsquo: '’', lsquo: '‘', ldquo: '“', rdquo: '”',
  times: '×', middot: '·', copy: '©', reg: '®', trade: '™', laquo: '«',
  raquo: '»', deg: '°', plusmn: '±', frac12: '½', shy: '',
};

/** Decode named and numeric entities. */
export function decode(s) {
  return String(s || '').replace(/&(#x?[0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]*);/g, (m, k) => {
    if (k[0] === '#') {
      const code = k[1] === 'x' || k[1] === 'X' ? parseInt(k.slice(2), 16) : parseInt(k.slice(1), 10);
      return Number.isFinite(code) ? String.fromCodePoint(code) : m;
    }
    const v = ENTITIES[k.toLowerCase()];
    return v === undefined ? m : v;
  });
}

/** Strip comments, scripts, styles and other non-prose blocks. */
function stripBlocks(html) {
  return String(html || '')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<script\b[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript\b[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<template\b[\s\S]*?<\/template>/gi, ' ')
    .replace(/<svg\b[\s\S]*?<\/svg>/gi, ' ');
}

/** Visible text of an HTML fragment. */
export function visibleText(html) {
  return decode(stripBlocks(html).replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
}

export function wordCount(s) {
  const t = String(s || '').replace(/\s+/g, ' ').trim();
  return t ? t.split(' ').length : 0;
}

/** Read one attribute from a tag string. Supports quoted and bare values. */
export function attr(tag, name) {
  const re = new RegExp(`\\b${name}\\s*=\\s*("([^"]*)"|'([^']*)'|([^\\s>]+))`, 'i');
  const m = String(tag || '').match(re);
  if (!m) return null;
  return decode(m[2] !== undefined ? m[2] : m[3] !== undefined ? m[3] : m[4]);
}

function tagAttrs(html, tagName) {
  return [...String(html || '').matchAll(new RegExp(`<${tagName}\\b([^>]*)>`, 'gi'))].map((m) => m[1]);
}

function firstTag(html, tagName) {
  const m = String(html || '').match(new RegExp(`<${tagName}\\b([^>]*)>`, 'i'));
  return m ? m[0] : null;
}

/** Slice the document at a region so offset checks can compare positions.
 *  Depth-aware: a `<div>` contains other divs, so the first `</div>` is not the
 *  end of the element. Counting open/close tags is enough for our own markup. */
function region(body, openRe, tagName) {
  const m = openRe.exec(body);
  if (!m) return null;
  const start = m.index;
  const re = new RegExp(`<(/?)\\s*${tagName}\\b[^>]*>`, 'gi');
  re.lastIndex = start;
  let depth = 0;
  let end = body.length;
  let t;
  while ((t = re.exec(body))) {
    if (t[1] === '/') {
      depth--;
      if (depth === 0) { end = t.index + t[0].length; break; }
    } else {
      depth++;
    }
  }
  return { start, end };
}

/** All Q/A pairs rendered as <details><summary>…</summary>…</details>. */
function extractFaq(body) {
  const out = [];
  for (const m of body.matchAll(/<details\b[^>]*>([\s\S]*?)<\/details>/gi)) {
    const inner = m[1];
    const sum = inner.match(/<summary\b[^>]*>([\s\S]*?)<\/summary>/i);
    if (!sum) continue;
    out.push({ q: visibleText(sum[1]), a: visibleText(inner.replace(sum[0], '')) });
  }
  return out;
}

/**
 * Stage 3 — parse one fetched document.
 *
 * @param {{url:string, finalUrl?:string, status:number, headers?:object, body:string, bytes?:number, chain?:array}} input
 */
export function parsePage(input) {
  const url = input.url;
  const finalUrl = input.finalUrl || input.url;
  const body = String(input.body || '');
  const headEnd = body.search(/<\/head>/i);
  const head = headEnd === -1 ? body : body.slice(0, headEnd);

  const metas = { name: {}, property: {} };
  for (const attrs of tagAttrs(head, 'meta')) {
    const content = attr(attrs, 'content');
    const name = attr(attrs, 'name');
    const property = attr(attrs, 'property');
    if (name && content !== null) metas.name[name.toLowerCase()] = content;
    if (property && content !== null) metas.property[property.toLowerCase()] = content;
  }

  const titleMatch = head.match(/<title\b[^>]*>([\s\S]*?)<\/title>/i);
  const title = titleMatch ? visibleText(titleMatch[1]) : null;

  const canonicalTag = firstTag(head, 'link');
  let canonical = null;
  for (const attrs of tagAttrs(head, 'link')) {
    if ((attr(attrs, 'rel') || '').toLowerCase() === 'canonical') canonical = attr(attrs, 'href');
  }
  void canonicalTag;

  const htmlTag = firstTag(body, 'html');
  const lang = htmlTag ? attr(htmlTag, 'lang') : null;

  const ldjson = [];
  for (const m of body.matchAll(/<script\b[^>]*type\s*=\s*["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)) {
    const raw = m[1].trim();
    try {
      ldjson.push({ raw, ok: true, data: JSON.parse(raw) });
    } catch (err) {
      ldjson.push({ raw, ok: false, error: String(err.message || err) });
    }
  }

  const headings = [...body.matchAll(/<h([1-6])\b[^>]*>([\s\S]*?)<\/h\1>/gi)].map((m) => ({
    level: Number(m[1]),
    text: visibleText(m[2]),
    offset: m.index,
  }));

  const links = [...body.matchAll(/<a\b([^>]*)>([\s\S]*?)<\/a>/gi)].map((m) => {
    const href = attr(m[1], 'href');
    let absolute = null;
    let internal = false;
    if (href) {
      try {
        const u = new URL(href, finalUrl);
        absolute = u.toString();
        internal = u.origin === new URL(finalUrl).origin;
      } catch { /* unparseable href is itself a finding candidate */ }
    }
    const rel = (attr(m[1], 'rel') || '').toLowerCase();
    return {
      href,
      absolute,
      internal,
      text: visibleText(m[2]),
      rel,
      nofollow: rel.split(/\s+/).includes('nofollow'),
      offset: m.index,
    };
  });

  const images = tagAttrs(body, 'img').map((attrs) => {
    const src = attr(attrs, 'src');
    let absolute = null;
    if (src) { try { absolute = new URL(src, finalUrl).toString(); } catch {} }
    return {
      src,
      absolute,
      alt: attr(attrs, 'alt'),
      width: attr(attrs, 'width'),
      height: attr(attrs, 'height'),
      loading: attr(attrs, 'loading'),
      offsets: attrs,
    };
  });

  // Embedded media. An iframe/embed without intrinsic dimensions shifts the
  // layout when it loads — the classic CLS culprit the visual pass flags.
  const iframes = [...body.matchAll(/<(?:iframe|embed)\b([^>]*)>/gi)].map((m) => ({
    src: attr(m[1], 'src'),
    width: attr(m[1], 'width'),
    height: attr(m[1], 'height'),
  }));

  const scriptTags = [...body.matchAll(/<script\b([^>]*)>/gi)].map((m) => ({
    src: attr(m[1], 'src'),
    async: /\basync\b/i.test(m[1]),
    defer: /\bdefer\b/i.test(m[1]),
    type: attr(m[1], 'type'),
  }));
  const scripts = scriptTags.filter((s) => s.src);
  // `type="module"` is deferred by definition, so it never blocks rendering.
  // Cloudflare injects a module beacon into every response; counting it as
  // blocking would put a permanent false finding in every report.
  const renderBlocking = scripts
    .filter((s) => !s.async && !s.defer && (s.type || '').toLowerCase() !== 'module')
    .map((s) => s.src);

  const styles = tagAttrs(head, 'link')
    .filter((a) => (attr(a, 'rel') || '').toLowerCase() === 'stylesheet')
    .map((a) => attr(a, 'href'));

  const preconnect = tagAttrs(head, 'link')
    .filter((a) => (attr(a, 'rel') || '').toLowerCase() === 'preconnect')
    .map((a) => attr(a, 'href'));

  // Ads: the <ins> blocks are the real units; the .ad-slot divs are the reserved
  // containers. Both are recorded because a container can exist with no unit.
  const insBlocks = [...body.matchAll(/<ins\b([^>]*)>/gi)].map((m) => ({
    slot: attr(m[1], 'data-ad-slot'),
    client: attr(m[1], 'data-ad-client'),
    offset: m.index,
  }));
  const adDivs = [...body.matchAll(/<div\b([^>]*class\s*=\s*["'][^"']*\bad-slot\b[^"']*["'][^>]*)>/gi)].map((m) => ({
    classes: attr(m[1], 'class') || '',
    empty: /\bad-slot--empty\b/.test(attr(m[1], 'class') || ''),
    ariaHidden: attr(m[1], 'aria-hidden'),
    offset: m.index,
  }));
  const loaderCount = (body.match(/pagead2\.googlesyndication\.com\/pagead\/js\/adsbygoogle\.js\?client=/g) || []).length;

  // Regions. Offsets are what let the brand rule prove that an ad sits outside
  // the tool rather than merely asserting it.
  const article = region(body, /<article\b[^>]*>/i, 'article');
  const toolShell = region(body, /<div\b[^>]*class\s*=\s*["'][^"']*\btool-shell\b[^"']*["'][^>]*>/i, 'div');
  const toolMain = region(body, /<article\b[^>]*class\s*=\s*["'][^"']*\btool-main\b[^"']*["'][^>]*>/i, 'article');
  const toolSide = region(body, /<aside\b[^>]*class\s*=\s*["'][^"']*\btool-side\b[^"']*["'][^>]*>/i, 'aside');
  const toolContent = region(body, /<section\b[^>]*class\s*=\s*["'][^"']*\btool-content\b[^"']*["'][^>]*>/i, 'section');

  const articleHtml = article ? body.slice(article.start, article.end) : '';
  const proseHtml = articleHtml.replace(/<details\b[\s\S]*?<\/details>/gi, ' ');
  const faq = extractFaq(articleHtml || body);

  const textBody = visibleText(body);
  const textArticle = visibleText(articleHtml);
  const textProse = visibleText(proseHtml);

  const path = (() => { try { return new URL(finalUrl).pathname; } catch { return url; } })();

  return {
    url,
    finalUrl,
    path,
    status: input.status,
    headers: input.headers || {},
    chain: input.chain || [],
    bytes: input.bytes ?? Buffer.byteLength(body),
    contentType: (input.headers || {})['content-type'] || null,

    title,
    description: metas.name['description'] || metas.property['og:description'] || null,
    canonical,
    robotsMeta: metas.name['robots'] || null,
    lang,
    viewport: metas.name['viewport'] || null,
    themeColor: metas.name['theme-color'] || null,

    og: {
      title: metas.property['og:title'] || null,
      description: metas.property['og:description'] || null,
      type: metas.property['og:type'] || null,
      url: metas.property['og:url'] || null,
      image: metas.property['og:image'] || null,
      imageWidth: metas.property['og:image:width'] || null,
      imageHeight: metas.property['og:image:height'] || null,
      imageAlt: metas.property['og:image:alt'] || null,
      siteName: metas.property['og:site_name'] || null,
    },
    twitter: {
      card: metas.name['twitter:card'] || null,
      title: metas.name['twitter:title'] || null,
      description: metas.name['twitter:description'] || null,
      image: metas.name['twitter:image'] || null,
    },

    jsonld: ldjson,
    headings,
    h1: headings.filter((h) => h.level === 1),
    links,
    images,
    iframes,
    scripts,
    styles,
    preconnect,
    renderBlocking,

    ads: { units: insBlocks, divs: adDivs, loaderCount },
    regions: { article, toolShell, toolMain, toolSide, toolContent },

    faq,
    text: { body: textBody, article: textArticle, prose: textProse },
    words: {
      body: wordCount(textBody),
      article: wordCount(textArticle),
      prose: wordCount(textProse),
    },

    flags: {
      consentBanner: /id="ck-banner"/.test(body),
      skipLink: /class="[^"]*skip/i.test(body),
      details: (body.match(/<details\b/gi) || []).length,
    },
  };
}
